/* Focused onboarding actions. All saves use the existing business models. */
const SetupPanel={create(d){
 const {model,committee,person,editor,drawer,closeDrawer,render,toast,h,setContext}=d;
 const $=s=>document.querySelector(s);let itemId='rooms';
 const rows=()=>model.read().records.filter(r=>!['已作废','已撤回'].includes(r.status));
 const leader=()=>['主任','副主任'].includes(person()?.role);
 const state=()=>ReadinessModel.derive(committee(),model.read());
 const now=()=>new Date().toISOString().slice(0,10);
 const demoFile=name=>[{key:'setup-demo-'+Date.now()+'-'+Math.random().toString(36).slice(2),name:name+'（示例）.txt',demo:true}];
 const formal=()=>committee().members.filter(m=>m.role!=='候补委员');
 const owner=()=>person()?.id||formal()[0]?.id;
 const reopen=()=>open(itemId);
 const button=(id,text)=>`<button class="secondary" id="${id}">${text}</button>`;
 const titleField={key:'title',label:'名称',type:'text',required:true};
 function examples(fields,overrides={}){const n=Math.floor(formal().length/2)+1;const values={title:'建档示例',note:'演示：已逐项核对示例材料，仅用于体验流程',parameters:'演示参数核对记录：会议召集、通知期限、表决方式及公示要求，正式使用时按本小区原文逐项填写。',original:'演示合同条款：物业负责公共区域保洁、秩序维护及设施日常巡查。',standard:'公共区域每日保洁；设施每日巡查；问题登记并反馈。仅为体验示例。',proof:'巡查记录、保洁记录及问题反馈单（示例）',attendees:String(n),agree:String(n),disagree:'0',abstain:'0',unvoted:'0',observers:'无',minutes:'演示会议纪要：讨论建档分工、确认职责安排；记录出席、议程、讨论、表决、决定与执行分工。',decision:'演示：通过建档职责安排，按分工完善资料。'};for(const f of fields){if(f.type==='file')values[f.key]=demoFile(f.label);if(f.type==='meeting')values[f.key]=rows().find(r=>r.module==='A4'&&['已定稿','已归档'].includes(r.status))?.id||''}return {...values,...overrides}}
 function newForm(module,type,initial,example){setContext(module,type);const def=model.def(module,type);editor('填写'+(initial.category||initial.duty||initial.kind||def.name),[titleField,...def.fields],initial,v=>model.add(module,type,v),'保存草稿',true,()=>examples(def.fields,example),reopen)}
 function continueRecord(id){const r=rows().find(r=>r.id===id);if(!r)return;setContext(r.module,r.type);const def=model.def(r.module,r.type),step=def.steps?.[r.stage];if(!step)return;try{model.allow(step.role,r)}catch(e){toast(e.message);return}const fields=step.fields?.length?step.fields:[{key:'confirmed',label:'我已核对以上材料与信息',type:'check',required:true}];editor(step.label,fields,{},v=>{if(!step.fields?.length&&!v.confirmed)throw Error('请先核对确认');model.next(r.id,v)},'确认并更新进度',!!step.fields?.length,()=>examples(fields),reopen)}
 function editRecord(id){const r=rows().find(r=>r.id===id);setContext(r.module,r.type);const def=model.def(r.module,r.type);editor('修改'+r.title,[titleField,...def.fields],r.fields,v=>model.edit(id,v),'保存草稿',false,null,reopen)}
 function record(r,complete){const def=model.def(r.module,r.type),step=def.steps?.[r.stage];return `<article class="setup-record"><strong>${h(r.title)}</strong><p>${h(r.number)} · ${h(r.status)}</p><div class="work-buttons">${r.status==='草稿'?`<button class="link" data-setup-edit="${r.id}">修改草稿</button>`:''}${!complete&&step?`<button class="primary" data-setup-next="${r.id}">${h(step.label)}</button>`:''}<button class="link" data-setup-source="${r.id}">查看完整记录</button></div></article>`}
 function phones(){const c=committee(),fields=c.members.filter(m=>!m.accountPhone).map(m=>({key:m.id,label:m.name+' · '+m.role,type:'tel',required:true}));if(!leader()){toast('请由主任或副主任补充手机号');return}if(!fields.length){toast('所有成员已认领，无需补充');return}const values=Object.fromEntries(c.members.map(m=>[m.id,m.phone||'']));editor('补充成员手机号',fields,values,v=>A0.store.updatePhones(A0.phone(),c.id,v),'保存手机号',true,()=>{const used=new Set(c.members.map(m=>m.phone).filter(Boolean));const out={};let n=101;for(const m of c.members.filter(m=>!m.accountPhone)){if(m.phone){out[m.id]=m.phone;continue}let phone;do{phone='1380000'+String(n++).padStart(4,'0')}while(used.has(phone));used.add(phone);out[m.id]=phone}return out},reopen)}
 function roomsForm(){setContext('A2','楼盘表');editor('批量填写楼盘表',[{key:'lines',label:'每行：楼栋,单元,房号',type:'textarea',required:true}],{},v=>model.importRooms(v.lines),'保存房屋草稿',true,()=>({lines:'1栋,1单元,101\n1栋,1单元,102\n1栋,1单元,201\n1栋,1单元,202'}),reopen)}
 function roomTotal(){const count=rows().filter(r=>r.module==='A2'&&r.type==='楼盘表').length;editor('填写房屋总数',[{key:'totalRooms',label:'房屋总数（须与完整房屋台账一致）',type:'number',required:true}],{totalRooms:model.read().readiness?.totalRooms||''},v=>model.configureReadiness({totalRooms:Number(v.totalRooms)}),'保存总数',true,()=>({totalRooms:count||4}),reopen)}
 function confirmInventory(){editor('核对现有印章清单',[{key:'confirmed',label:'以上使用中的印章及保管人已完整登记并核对',type:'check',required:true}],{},v=>{if(!v.confirmed)throw Error('请核对后确认');model.configureReadiness({sealsConfirmed:true})},'确认清单并更新进度',false,null,reopen)}
 function open(id){itemId=id;const i=state().items.find(x=>x.id===id);if(!i)return;let body=`<p class="a0-note">${h(i.description)}</p><p class="setup-template-note">“载入示例”只填入可修改的演示内容，保存后仍需核对确认。不会替代真实材料或身份认证。</p>`;const list=rows();
 if(id==='rooms'){const rs=list.filter(r=>r.module==='A2'&&r.type==='楼盘表');body+=`<div class="work-buttons">${button('setup-room-add','填写楼盘表')}${button('setup-room-total','设置房屋总数')}${rs.some(r=>r.status==='草稿')?button('setup-room-lock','核对并锁定房屋'):''}</div>${rs.map(r=>record(r,r.status==='已锁定')).join('')}`}
 if(id==='rules'){for(const category of ['管理规约','业主大会议事规则','业委会工作规则']){const rs=list.filter(r=>r.module==='A2'&&r.type==='三规'&&r.fields.category===category);body+=`<section class="setup-record"><h3>${category}</h3><button class="secondary" data-setup-rule="${category}">填写${rs.length?'新版本':'材料'}</button>${rs.map(r=>record(r,r.status==='已归档')).join('')}</section>`}}
 if(id==='property'){const rs=list.filter(r=>r.module==='A3');body+=button('setup-property-add','填写物业服务合同')+rs.map(r=>record(r,['履行中','已评估'].includes(r.status))).join('')}
 if(id==='members'){body+=`<h3>1. 成员手机号</h3>${committee().members.map(m=>`<p>${h(m.name)} · ${h(m.role)} · ${m.phone?h(m.phone.slice(0,3)+'****'+m.phone.slice(7)):'待补手机号'}</p>`).join('')}${button('setup-phones','填写手机号')}<h3>2. 职责分工</h3><p class="a0-note">选择主办、协办，保存后关联已定稿会议使分工生效。未配置的职责由主任暂领。</p>`;for(const duty of ReadinessModel.duties){const r=list.find(r=>r.module==='A17'&&r.type==='职责分工'&&r.fields.duty===duty);body+=r?record(r,r.status==='已生效'):`<p><button class="secondary" data-setup-duty="${duty}">填写${duty}分工</button></p>`}body+=`<h3>3. 分工会议依据</h3><p class="a0-note">可选择已有定稿会议。若只体验流程，可新建演示会议并依次确认安排、签到和纪要。</p>${button('setup-meeting-add','填写分工会议（演示）')}`+list.filter(r=>r.module==='A4').map(r=>record(r,['已定稿','已归档'].includes(r.status))).join('')}
 if(id==='seals'){body+=button('setup-seal-add','填写印章台账')+list.filter(r=>r.module==='A18'&&r.type==='印章台账').map(r=>record(r,['使用中','已停用'].includes(r.status))).join('')+button('setup-seal-confirm','核对现有印章清单')}
 if(id==='filing'){body+=`<p>${h(committee().file?.name||'暂无材料')}</p><p>状态：${h(i.status)}</p>${button('setup-filing','查看归档原件')}`}
 if(id==='chair'){const m=committee().members.find(m=>m.role==='主任');body+=`<p>主任：${h(m?.name||'未配置')} · ${m?.phone?h(m.phone.slice(0,3)+'****'+m.phone.slice(7)):'未登记手机号'}</p><p>${i.done?'已通过手机号登录并确认身份。':'请先补充主任手机号，再由主任本人登录认领。不能通过填充模板代替身份确认。'}</p>${button('setup-phones','补充手机号')}${button('setup-account','查看账号 / 切换登录')}`}
 if(i.excluded)body+=`<p>当前不适用：${h(i.reason)}。如需办理，请先在“配置建档”清除不适用原因。</p>`;
 drawer(i.title+` · ${i.status}`,body);
 const on=(id,fn)=>{if($('#'+id))$('#'+id).onclick=fn};
 document.querySelectorAll('[data-setup-next]').forEach(b=>b.onclick=()=>continueRecord(b.dataset.setupNext));document.querySelectorAll('[data-setup-edit]').forEach(b=>b.onclick=()=>editRecord(b.dataset.setupEdit));document.querySelectorAll('[data-setup-source]').forEach(b=>b.onclick=()=>{const r=list.find(r=>r.id===b.dataset.setupSource);closeDrawer();d.navigate(r.module,r.type,r.id)});
 on('setup-room-add',roomsForm);on('setup-room-total',roomTotal);on('setup-room-lock',()=>editor('核对房屋台账',[{key:'confirmed',label:'已逐项核对当前所有房屋草稿，确认锁定',type:'check',required:true}],{},v=>{if(!v.confirmed)throw Error('请确认');model.lockRooms()},'确认锁定并更新进度',false,null,reopen));
 document.querySelectorAll('[data-setup-rule]').forEach(b=>b.onclick=()=>{const category=b.dataset.setupRule;newForm('A2','三规',{category},{title:category+'（演示）',category,version:'示例 v1.0',effective:now(),passedAt:now(),passedBy:'示例：业主大会 / 业委会，请按原文填写',custodian:owner(),evidence:demoFile(category)})});
 on('setup-property-add',()=>newForm('A3','',{}, {title:'物业服务合同（演示）',company:'示例物业服务有限公司',start:now(),end:(new Date().getFullYear()+1)+'-12-31',hotline:'示例：请填合同约定的服务电话',fee:'示例：按合同约定的项目、单价、计费面积和周期填写',share:'示例：按合同核对共有收益分配约定',evidence:demoFile('物业服务合同')}));
 on('setup-phones',phones);document.querySelectorAll('[data-setup-duty]').forEach(b=>b.onclick=()=>{const duty=b.dataset.setupDuty;newForm('A17','职责分工',{duty},{title:duty+'分工（演示）',duty,owner:owner(),helperIds:formal().filter(m=>m.id!==owner()).slice(0,1).map(m=>m.id),helpers:'演示：协助整理和核对资料'})});
 on('setup-meeting-add',()=>newForm('A4','',{}, {title:'建档分工会议（演示）',time:now()+'T14:00',place:'小区会议室（示例）',agenda:'审议建档职责分工与资料完善安排',owner:owner()}));
 on('setup-seal-add',()=>newForm('A18','印章台账',{}, {title:'业委会公章（演示）',kind:'公章',custodian:owner(),stampDate:now(),evidence:demoFile('印章登记材料')}));on('setup-seal-confirm',confirmInventory);
 on('setup-filing',()=>{closeDrawer();A0.previewArchive()});on('setup-account',()=>{closeDrawer();document.querySelector('#a0-account')?.click()});
 }
 return {open};
}};
